mapper.select:
			SELECT * FROM yh_temporary_programs_template as ypt
			LEFT JOIN yh_programs_dictionary as ypd
			ON ypt.plan_content=ypd.plancount_id
			WHERE

               ypt.Intervention_id IS NULL


               ypt.Intervention_id=#{interventionId}

			 and ypt.usercode=#{usercode}
              ORDER BY ypt.programs_weeks,ypt.programs_days
              LIMIT #{start},#{limit}

mapper.delete:
DELETE   FROM yh_temporary_programs_template WHERE

  Intervention_id is NULL


 Intervention_id=#{interventionId}


 and usercode=#{usercode}

mapper.select:
SELECT COUNT(*) FROM  yh_temporary_programs_template WHERE

  Intervention_id IS  NULL


  Intervention_id=#{interventionId}

 and usercode=#{usercode}

mapper.update:
UPDATE yh_temporary_programs_template
SET Intervention_id=#{interventionId}
where usercode=#{usercode} and Intervention_id is null
